function Dialog({ title, message, actions, children }) {
  return (
    <div className="dialog">
      <h3>{title}</h3>
      <p>{message}</p>
      {children}
      <div className="actions">{actions}</div>
    </div>
  );
}

function WelcomeDialog() {
  return (
    <Dialog
      title="Welcome"
      message="Thank you for visiting."
      actions={<button>Got it</button>}
    />
  );
}
function ConfirmDelete({ name }) {
  return (
    <Dialog
      title="Delete?"
      message={"Delete " + name + " permanently?"}
      actions={<><button>Cancel</button> <button style={{ color: "crimson" }}>Delete</button></>}
    >
      <small>This cannot be undone.</small>
    </Dialog>
  );
}

function App() {
  return <div style={{ fontFamily: "sans-serif", padding: 12 }}><WelcomeDialog /><ConfirmDelete name="report.pdf" /></div>;
}

function List({ items, renderItem, empty = <p>Nothing here</p> }) {
  if (items.length === 0) return empty;
  return <ul>{items.map((item, i) => <li key={item.id}>{renderItem(item, i)}</li>)}</ul>;
}

function Toggle({ children }) {
  const [on, setOn] = useState(false);
  return children({ on, toggle: () => setOn(!on) });
}

function App() {
  const fruits = [{ id: 1, name: "Apple" }, { id: 2, name: "Banana" }];
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <List items={fruits} renderItem={(f, i) => <b>{i + 1}. {f.name}</b>} />
      <List items={[]} renderItem={() => null} />
      <Toggle>
        {({ on, toggle }) => <button onClick={toggle}>Light is {on ? "ON" : "OFF"}</button>}
      </Toggle>
    </div>
  );
}

topics.description:
A **higher-order component** is a function `withX(Component)` that returns a new component adding behavior. It is function composition applied to components.

```jsx
function withLoading(Wrapped) {
  return function WithLoading({ loading, ...props }) {
    if (loading) return <p>Loading...</p>;
    return <Wrapped {...props} />;
  };
}
const UserListWithLoading = withLoading(UserList);
```

### Real-world HOCs

`connect()` in old Redux, `withRouter` in old React Router, `React.memo` (a built-in HOC), `withAuth(Page)`, `styled(Button)`.

### Rules for writing good HOCs

- **Do not mutate** the wrapped component; wrap it.
- **Pass through** all unrelated props with `{...props}`.
- **Never create HOCs inside render** - a new component type each render remounts the tree and loses state.
- Set a **`displayName`** (e.g. `withLoading(UserList)`) for DevTools.
- **Static methods and refs** are not forwarded automatically (use `forwardRef`, `hoist-non-react-statics`).
- Compose several HOCs with a `compose` helper.

### Downsides

- "Wrapper hell" in DevTools.
- Prop name collisions between HOCs.
- Harder to follow data flow and to type with TypeScript.

### Today

Hooks replaced most use cases. HOCs still appear in legacy code, libraries, and for cross-cutting concerns like auth guards, error boundary wrappers, and analytics.

examples.code:
function withHover(Wrapped) {
  function WithHover(props) {
    const [hover, setHover] = useState(false);
    return (
      <div onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}>
        <Wrapped {...props} hover={hover} />
      </div>
    );
  }
  WithHover.displayName = "withHover(" + (Wrapped.displayName || Wrapped.name) + ")";
  return WithHover;
}

function Card({ title, hover }) {
  return (
    <div style={{ padding: 14, border: "2px solid", borderColor: hover ? "#0ea5e9" : "#ccc", borderRadius: 8, transition: ".2s" }}>
      {title} {hover && "(hovering)"}
    </div>
  );
}
const HoverCard = withHover(Card); // created OUTSIDE the component

function App() {
  return <div style={{ fontFamily: "sans-serif", padding: 12 }}><HoverCard title="Move your mouse here" /></div>;
}

const TabsCtx = createContext(null);

function Tabs({ defaultValue, children }) {
  const [value, setValue] = useState(defaultValue);
  return <TabsCtx.Provider value={{ value, setValue }}>{children}</TabsCtx.Provider>;
}
function useTabs() {
  const c = useContext(TabsCtx);
  if (!c) throw new Error("Tabs.* must be used inside <Tabs>");
  return c;
}
Tabs.List = function List({ children }) {
  return <div role="tablist" style={{ display: "flex", gap: 4, borderBottom: "1px solid #ccc" }}>{children}</div>;
};
Tabs.Tab = function Tab({ value, children }) {
  const { value: active, setValue } = useTabs();
  const on = active === value;
  return (
    <button role="tab" aria-selected={on} onClick={() => setValue(value)}
      style={{ padding: "6px 12px", border: 0, borderBottom: on ? "3px solid #0ea5e9" : "3px solid transparent", background: "none", cursor: "pointer" }}>
      {children}
    </button>
  );
};
Tabs.Panel = function Panel({ value, children }) {
  const { value: active } = useTabs();
  return active === value ? <div role="tabpanel" style={{ padding: 10 }}>{children}</div> : null;
};

function App() {
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <Tabs defaultValue="a">
        <Tabs.List>
          <Tabs.Tab value="a">React</Tabs.Tab>
          <Tabs.Tab value="b">Vue</Tabs.Tab>
        </Tabs.List>
        <Tabs.Panel value="a">React is a UI library.</Tabs.Panel>
        <Tabs.Panel value="b">Vue is a progressive framework.</Tabs.Panel>
      </Tabs>
    </div>
  );
}

function useControllable(value, defaultValue, onChange) {
  const [inner, setInner] = useState(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? value : inner;
  const set = (v) => {
    if (!controlled) setInner(v);
    if (onChange) onChange(v);
  };
  return [current, set];
}

function Stepper({ value, defaultValue = 0, onChange }) {
  const [n, setN] = useControllable(value, defaultValue, onChange);
  return (
    <span>
      <button onClick={() => setN(n - 1)}>-</button> {n} <button onClick={() => setN(n + 1)}>+</button>
    </span>
  );
}

function App() {
  const [v, setV] = useState(5);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>Uncontrolled: <Stepper defaultValue={2} /></p>
      <p>Controlled: <Stepper value={v} onChange={setV} /> parent knows: {v}</p>
      <button onClick={() => setV(0)}>Parent resets controlled to 0</button>
    </div>
  );
}

// presentational: knows nothing about where data comes from
function UserList({ users, loading, onSelect }) {
  if (loading) return <p>Loading...</p>;
  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}><button onClick={() => onSelect(u)}>{u.name}</button></li>
      ))}
    </ul>
  );
}

// logic lives in a hook (the modern "container")
function useUsers() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    const t = setTimeout(() => {
      setUsers([{ id: 1, name: "Asha" }, { id: 2, name: "Ravi" }]);
      setLoading(false);
    }, 500);
    return () => clearTimeout(t);
  }, []);
  return { users, loading };
}

function App() {
  const { users, loading } = useUsers();
  const [picked, setPicked] = useState(null);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <UserList users={users} loading={loading} onSelect={setPicked} />
      {picked && <p>Selected: <b>{picked.name}</b></p>}
    </div>
  );
}

function Modal({ open, onClose, title, children }) {
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => e.key === "Escape" && onClose();
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  if (!open) return null;
  return ReactDOM.createPortal(
    <div className="overlay" onClick={onClose}>
      <div className="dialog" role="dialog" aria-modal="true" aria-label={title} onClick={(e) => e.stopPropagation()}>
        <h3>{title}</h3>
        {children}
        <button onClick={onClose}>Close</button>
      </div>
    </div>,
    document.body
  );
}

function App() {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12, overflow: "hidden", height: 60 }}>
      <button onClick={() => setOpen(true)}>Open modal</button>
      <Modal open={open} onClose={() => setOpen(false)} title="Hello">
        <p>I am rendered into document.body. Press Escape to close.</p>
      </Modal>
    </div>
  );
}

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { error: null };
  }
  static getDerivedStateFromError(error) {
    return { error };
  }
  componentDidCatch(error, info) {
    console.log("Logged:", error.message);
  }
  render() {
    if (this.state.error) {
      return (
        <div style={{ color: "crimson" }}>
          <p>Something went wrong: {this.state.error.message}</p>
          <button onClick={() => this.setState({ error: null })}>Try again</button>
        </div>
      );
    }
    return this.props.children;
  }
}

function Bomb({ explode }) {
  if (explode) throw new Error("Boom from child");
  return <p>All fine.</p>;
}

function App() {
  const [explode, setExplode] = useState(false);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setExplode(true)}>Trigger error</button>
      <ErrorBoundary key={String(explode)}>
        <Bomb explode={explode} />
      </ErrorBoundary>
    </div>
  );
}

const HeavyChart = lazy(
  () =>
    new Promise((resolve) =>
      setTimeout(
        () =>
          resolve({
            default: function HeavyChart() {
              return <div style={{ padding: 10, background: "#e0f2fe" }}>Chart loaded!</div>;
            },
          }),
        800
      )
    )
);

function App() {
  const [show, setShow] = useState(false);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setShow(true)}>Load chart</button>
      {show && (
        <Suspense fallback={<p>Loading chart...</p>}>
          <HeavyChart />
        </Suspense>
      )}
    </div>
  );
}

topics.description:
Many bugs come from boolean soup: `isLoading`, `isError`, `isSuccess`, `isSubmitting` can all become `true` at once even though only one makes sense. A **finite state machine** says: the UI is in exactly **one state** at a time, and only certain **events** move it to another state.

### Example: fetch machine

```
idle --FETCH--> loading --RESOLVE--> success
                  |  \--REJECT--> error --RETRY--> loading
```

### In plain React

Use a single `status` string and a `useReducer` where each state only handles allowed events.

```jsx
function reducer(state, event) {
  switch (state.status) {
    case "idle":    return event.type === "FETCH" ? { status: "loading" } : state;
    case "loading": return event.type === "RESOLVE" ? { status: "success", data: event.data }
                         : event.type === "REJECT" ? { status: "error", error: event.error } : state;
    case "error":   return event.type === "RETRY" ? { status: "loading" } : state;
    default: return state;
  }
}
```

### Benefits

- **Impossible states become impossible.**
- Easy to draw, review and test.
- Clear places to put side effects (entering "loading" triggers the request).

### Tools

**XState** (with `@xstate/react`) provides full machines, statecharts, guards, actors and visualizers. Use it for wizards, checkout flows, media players and complex forms. For small cases a reducer is enough.

### Discriminated unions

In TypeScript model states as a union keyed by `status`, so `data` only exists in `success`.

examples.code:
function reducer(state, event) {
  switch (state.status) {
    case "idle":
      return event.type === "FETCH" ? { status: "loading" } : state;
    case "loading":
      if (event.type === "RESOLVE") return { status: "success", data: event.data };
      if (event.type === "REJECT") return { status: "error", error: event.error };
      return state;
    case "success":
    case "error":
      return event.type === "FETCH" ? { status: "loading" } : state;
    default:
      return state;
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, { status: "idle" });
  const attempt = useRef(0);

  useEffect(() => {
    if (state.status !== "loading") return;
    const t = setTimeout(() => {
      attempt.current += 1;
      if (attempt.current % 2 === 1) dispatch({ type: "REJECT", error: "Network down" });
      else dispatch({ type: "RESOLVE", data: "Here is your data" });
    }, 600);
    return () => clearTimeout(t);
  }, [state.status]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>Status: <b>{state.status}</b></p>
      <button onClick={() => dispatch({ type: "FETCH" })} disabled={state.status === "loading"}>
        {state.status === "error" ? "Retry" : "Fetch"}
      </button>
      {state.status === "success" && <p>{state.data}</p>}
      {state.status === "error" && <p style={{ color: "crimson" }}>{state.error}</p>}
    </div>
  );
}
